function slugify(value=""){const map={а:"a",ә:"a",б:"b",в:"v",г:"g",ғ:"g",д:"d",е:"e",ё:"e",ж:"zh",з:"z",и:"i",й:"i",к:"k",қ:"q",л:"l",м:"m",н:"n",ң:"n",о:"o",ө:"o",п:"p",р:"r",с:"s",т:"t",у:"u",ұ:"u",ү:"u",ф:"f",х:"h",һ:"h",ц:"c",ч:"ch",ш:"sh",щ:"sh",ы:"y",і:"i",э:"e",ю:"yu",я:"ya",ь:"",ъ:""};return String(value).toLowerCase().split("").map((char)=>map[char]??char).join("").normalize("NFKD").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"sabak";}
