async function loadPresentationPreview(){const viewer=app.querySelector("#presentation-viewer");if(!viewer)return;try{const response=await fetch(viewer.dataset.url);if(!response.ok)throw new Error("Слайдтар ашылмады");const deck=await response.json();if(!deck.slides?.length)throw new Error("Слайдтар табылмады");viewer.innerHTML=`<div class="presentation-toolbar"><strong>${deck.slides.length} слайд</strong><div><button type="button" data-slide-nav="prev">↑</button><button type="button" data-slide-nav="next">↓</button></div></div><div class="presentation-scroll">${deck.slides.map((slide)=>`<article class="presentation-slide" id="preview-slide-${slide.number}" style="aspect-ratio:${deck.width}/${deck.height};background:${escapeHtml(slide.background)}"><span class="slide-number">${slide.number}</span>${slide.elements.map((element)=>element.type==="image"?`<img src="${escapeHtml(element.src)}" alt="" style="left:${element.x}%;top:${element.y}%;width:${element.w}%;height:${element.h}%"/>`:`<div class="slide-text" style="left:${element.x}%;top:${element.y}%;width:${element.w}%;height:${element.h}%;background:${escapeHtml(element.fill)};border-color:${escapeHtml(element.line)};color:${escapeHtml(element.color)};text-align:${element.align};font-size:clamp(7px,${Math.max(.8,Number(element.font_size||18)/7.2)}cqw,72px)">${escapeHtml(element.text).replace(/\n/g,"<br>")}</div>`).join("")}</article>`).join("")}</div>`;let current=0;const slides=[...viewer.querySelectorAll(".presentation-slide")];viewer.querySelectorAll("[data-slide-nav]").forEach((button)=>button.addEventListener("click",()=>{current=Math.max(0,Math.min(slides.length-1,current+(button.dataset.slideNav==="next"?1:-1)));slides[current].scrollIntoView({behavior:"smooth",block:"start"});}));}catch(error){viewer.innerHTML=`<div class="presentation-error">${escapeHtml(error.message)}</div>`;}}

function themeFromForm(form){const data=new FormData(form),settings={...DEFAULT_THEME,...state.settings};for(const key of ["site_title","font_family","heading_font","background","surface","text","muted","school","university","bridge","diagnostic","density","header_style","hero_style","card_style","home_layout","background_style","shadow_style"])if(data.has(key))settings[key]=String(data.get(key)||settings[key]);for(const key of ["base_size","heading_scale","card_radius","button_radius","content_width","page_gutter"])if(data.has(key))settings[key]=Number(data.get(key)||settings[key]);settings.visual_effects=data.get("visual_effects")==="on";settings.interface_version=2;return settings;}
function handleThemePreview(event){const form=event.currentTarget;if(event.target.matches('input[type="color"]')){const text=form.querySelector(`[data-color-text="${event.target.name}"]`);if(text)text.value=event.target.value;}if(event.target.matches("[data-color-text]")){const color=form.elements[event.target.dataset.colorText];if(/^#[0-9a-f]{6}$/i.test(event.target.value)&&color)color.value=event.target.value;}state.settings=themeFromForm(form);applyTheme();form.querySelectorAll('input[type="range"]').forEach((input)=>{const output=input.closest("label")?.querySelector("output");if(output)output.textContent=`${input.value}${input.name==="heading_scale"?"%":"px"}`;});const title=form.querySelector(".theme-preview h3");if(title)title.textContent=state.settings.site_title;}
async function handleThemeSave(event){event.preventDefault();const error=app.querySelector("#theme-error");try{state.settings={...DEFAULT_THEME,...await store.saveSettings(themeFromForm(event.currentTarget))};applyTheme();showToast("Дизайн сақталды");}catch(err){error.textContent=err.message||"Қате";}}

async function handleAuth(event){
 event.preventDefault();const form=event.currentTarget,data=new FormData(form),error=form.querySelector('#auth-error'),button=form.querySelector('[type="submit"]'),register=form.dataset.mode==='register';
 error.textContent='';if(!form.checkValidity()){error.textContent='Міндетті өрістерді дұрыс толтырыңыз';form.reportValidity();return;}
 const payload={displayName:String(data.get('displayName')||'').trim(),username:String(data.get('username')||'').trim(),email:String(data.get('email')||'').trim(),password:String(data.get('password')||''),role:'student'};
 if(register&&!payload.displayName){error.textContent='Аты-жөніңізді енгізіңіз';return;}button.disabled=true;button.textContent='Жүктелуде...';
 try{const result=register?await store.register(payload):await store.login(payload);if(result.confirmationRequired){error.style.color='#137652';error.textContent='Тіркелу сәтті аяқталды. Email-ге жіберілген сілтемені ашып, тіркелуді растаңыз. Содан кейін жүйеге кіріңіз';return;}state.user=result;state.resources={};state.items=normalizeItems(await store.listContent(result.role==='admin'));await refreshCatalog();if(result.role==='admin')state.users=await store.listUsers();else state.progress=await store.getProgress();navigate(result.role==='admin'?'/admin':'/');showToast(register?'Тіркелу сәтті аяқталды':'Жүйеге сәтті кірдіңіз');}
 catch(err){error.textContent=errorMessage(err);}finally{button.disabled=false;button.textContent=register?'Тіркелу':'Кіру';}
}

async function handleContentSave(event){
  event.preventDefault();
  const form=new FormData(event.currentTarget),error=app.querySelector("#content-error");
  const questions=[...event.currentTarget.querySelectorAll(".quiz-question")].map((node)=>({question:node.querySelector(".quiz-question-text").value.trim(),options:[...node.querySelectorAll(".quiz-option")].map((input)=>input.value.trim()),correct_index:Number(node.querySelector(".quiz-correct").value||0)})).filter((quiz)=>quiz.question);
  const invalid=questions.find((quiz)=>quiz.options.filter(Boolean).length<2||!quiz.options[quiz.correct_index]);
  if(invalid){error.textContent="Әр тест сұрағына кемінде екі жауап және дұрыс жауап енгізіңіз";return;}
  const input={title:String(form.get("title")||"").trim(),path:String(form.get("path")||"").trim(),area:form.get("area"),item_type:form.get("item_type")||"lesson",content_mode:form.get("content_mode")||"curriculum",parent_id:form.get("parent_id")||null,sort_order:Number(form.get("sort_order")||0),body:sanitizeRichText(app.querySelector("#rich-body")?.innerHTML||""),video_url:String(form.get("video_url")||"").trim(),quiz_data:questions.length?{questions}:{},is_published:form.get("is_published")==="on"};
  if(!input.title||!input.path.startsWith("/")){error.textContent="Атау мен URL-ді тексеріңіз";return;}
  try{
    if(state.editing==="new"){const created=await store.createContent(input);state.editing=created.id;state.newParentId=null;state.newItemType="lesson";state.editorTab=input.content_mode==="resources"?"files":"material";state.items=normalizeItems(await store.listContent(true));await loadResources(created.id,true);render();showToast("Сақталды. Енді материал мен файл қосуға болады");}
    else{await store.updateContent(state.editing,input);state.items=normalizeItems(await store.listContent(true));render();showToast("Сәтті сақталды");}
  }catch(err){error.textContent=err.message||"Қате";}
}
async function handleUpload(event){
 const input=event.target,files=[...(input.files||[])],itemId=state.editing;if(!files.length)return;input.disabled=true;const status=document.createElement('p');status.setAttribute('role','status');input.parentElement.append(status);let done=0;
 try{for(const file of files){validateFile(file);status.textContent=`${file.name}: Жүктелуде...`;await store.uploadResource(itemId,file,p=>status.textContent=`${file.name}: ${p}%`);done++;}showToast('Материал сәтті жүктелді');}
 catch(error){showToast(`${done} файл жүктелді. ${errorMessage(error)}`,'error');}
 finally{await loadResources(itemId,true).catch(()=>{});await refreshCatalog().catch(()=>{});state.editorTab='files';render();}
}

async function handleProgress(event){event.preventDefault();const form=new FormData(event.currentTarget);const progress=Number(form.get("progress"));try{await store.saveProgress(event.currentTarget.dataset.item,{progress,completed:form.get("completed")==="on"||progress===100});state.progress=await store.getProgress();render();showToast("Сәтті сақталды");}catch(error){showToast(error.message,"error");}}
async function handleQuiz(event){event.preventDefault();const form=new FormData(event.currentTarget),fields=[...event.currentTarget.querySelectorAll("fieldset")],answers=[];let score=0;for(let index=0;index<fields.length;index++){const answer=form.get(`answer_${index}`);if(answer===null){app.querySelector("#quiz-error").textContent="Барлық сұраққа жауап беріңіз";fields[index].scrollIntoView({behavior:"smooth",block:"center"});return;}answers.push(Number(answer));if(Number(answer)===Number(fields[index].dataset.correct))score++;}try{await store.submitQuiz(event.currentTarget.dataset.item,answers);state.progress=await store.getProgress();render();showToast(`Нәтиже: ${score} дұрыс, ${fields.length-score} қате`,score===fields.length?"success":"error");window.setTimeout(()=>document.querySelector(".quiz-result")?.scrollIntoView({behavior:"smooth",block:"center"}),40);}catch(error){showToast(error.message,"error");}}
async function handleDelete(){try{if(state.deleting.kind==="resource"){const itemId=state.deleting.itemId;await store.deleteResource(state.deleting.id);await loadResources(itemId,true);const parent=state.items.find(i=>i.id===itemId);if(parent?.path.startsWith("/material/")&&!state.resources[itemId].length){await store.deleteContent(itemId);state.items=normalizeItems(await store.listContent(true));}}else{await store.deleteContent(state.deleting.id);state.items=await store.listContent(true);}state.deleting=null;await refreshCatalog();render();showToast("Материал өшірілді");}catch(error){state.deleting=null;render();showToast(error.message,"error");}}
async function moveItem(id,direction){const current=state.items.find((item)=>item.id===id);if(!current)return;const list=state.items.filter((item)=>item.area===current.area&&item.parent_id===current.parent_id).sort((a,b)=>a.sort_order-b.sort_order),index=list.findIndex((item)=>item.id===id),target=index+direction;if(target<0||target>=list.length)return;list.splice(target,0,list.splice(index,1)[0]);try{await store.reorderContent(list.map((item)=>item.id));state.items=normalizeItems(await store.listContent(true));render();showToast(`${target+1}-орынға жылжытылды`);}catch(error){showToast(error.message||"Реттеу қатесі","error");}}
function initBuilderDragDrop(){app.querySelectorAll(".builder-row").forEach((row)=>{const id=row.querySelector('[data-action="edit"]')?.dataset.id,handle=row.querySelector(".builder-handle");if(!id||!handle)return;row.dataset.dragId=id;handle.setAttribute("tabindex","0");handle.setAttribute("role","button");handle.setAttribute("aria-label","Мышкамен жылжыту");handle.addEventListener("mousedown",()=>{row.draggable=true;});row.addEventListener("dragstart",(event)=>{draggedContentId=id;row.classList.add("dragging");event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",id);});row.addEventListener("dragover",(event)=>{const dragged=state.items.find((item)=>item.id===draggedContentId),target=state.items.find((item)=>item.id===id);if(!dragged||!target||dragged.parent_id!==target.parent_id||dragged.id===target.id)return;event.preventDefault();app.querySelectorAll(".builder-row.drop-before,.builder-row.drop-after").forEach((node)=>node.classList.remove("drop-before","drop-after"));row.classList.add(event.clientY<row.getBoundingClientRect().top+row.offsetHeight/2?"drop-before":"drop-after");});row.addEventListener("drop",async(event)=>{event.preventDefault();const after=row.classList.contains("drop-after");await reorderByDrop(draggedContentId,id,after);});row.addEventListener("dragend",()=>{draggedContentId=null;row.draggable=false;app.querySelectorAll(".builder-row").forEach((node)=>node.classList.remove("dragging","drop-before","drop-after"));});});}
async function reorderByDrop(draggedId,targetId,after){const dragged=state.items.find((item)=>item.id===draggedId),target=state.items.find((item)=>item.id===targetId);if(!dragged||!target||dragged.parent_id!==target.parent_id)return;const siblings=state.items.filter((item)=>item.area===dragged.area&&item.parent_id===dragged.parent_id).sort((a,b)=>a.sort_order-b.sort_order),ordered=siblings.filter((item)=>item.id!==draggedId),targetIndex=ordered.findIndex((item)=>item.id===targetId);ordered.splice(targetIndex+(after?1:0),0,dragged);try{await store.reorderContent(ordered.map((item)=>item.id));state.items=normalizeItems(await store.listContent(true));render();showToast("Реті сақталды");}catch(error){showToast(error.message||"Реттеу қатесі","error");}}
async function loadResources(itemId,force=false){if(!force&&state.resources[itemId])return;state.resources[itemId]=await store.listResources(itemId);}
async function hydrateRoute(){const path=routePath();const item=byPath(path);if(!item||["school-root","university-root","bridge-root"].includes(item.id))return;try{await loadResources(item.id);if(state.user&&state.user.role!=="admin"&&!state.viewed.has(item.id)){state.viewed.add(item.id);await store.recordView(item.id);state.progress=await store.getProgress();}render();}catch(error){showToast(error.message,"error");}}

document.addEventListener("selectionchange",saveRichSelection);
window.addEventListener("popstate",()=>{render();hydrateRoute();});
async function refreshCatalog(){state.allResources=await store.listAllResources();state.resources={};for(const item of state.items)state.resources[item.id]=state.allResources.filter(r=>r.item_id===item.id);if(store.mode==='local-server'||window.__CHEM_CONFIG__?.schemaVersion>=2)state.popularity=await store.listPopularity().catch(()=>[]);}
async function openResource(id,download=false){
 const resource=state.allResources.find(r=>r.id===id)||Object.values(state.resources).flat().find(r=>r.id===id);if(!resource)return showToast('Файл табылмады','error');
 try{const url=await store.resourceUrl(resource,download);if(download){showToast('Файл жүктелуде...');const response=await fetch(url+(store.mode==='local-server'?'?download=1':''),{signal:AbortSignal.timeout(60000)});if(!response.ok)throw new Error('Файлды жүктеп алу мүмкін болмады. Қайта әрекет жасаңыз');const blobUrl=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=blobUrl;a.download=resource.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(blobUrl),60000);showToast('Файлды жүктеп алу басталды');}else{state.previewing={...resource,url};render();}}catch(error){showToast(error.message,'error');}
}
function bindCatalogActions(){
 app.querySelectorAll('[data-open-resource]').forEach(b=>b.addEventListener('click',()=>openResource(b.dataset.openResource)));
 app.querySelectorAll('[data-download-resource]').forEach(b=>b.addEventListener('click',()=>openResource(b.dataset.downloadResource,true)));
 app.querySelectorAll('[data-edit-material]').forEach(b=>b.addEventListener('click',()=>navigate('/admin/material/'+b.dataset.editMaterial)));
 app.querySelectorAll('[data-publish-material]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{const id=b.dataset.publishMaterial;if(id.startsWith('resource:')){const r=state.allResources.find(r=>r.id===id.slice(9));await store.updateResourceMetadata(r.id,{is_published:r.is_published===false||r.is_published===0});await refreshCatalog();render();showToast('Жариялану күйі өзгертілді');}else{const item=state.items.find(i=>i.id===id);await store.updateContent(item.id,store.mode==='local-server'?{...item,is_published:!item.is_published}:{is_published:!item.is_published});state.items=normalizeItems(await store.listContent(true));render();}}catch(error){b.disabled=false;showToast(error.message,'error');}}));
}
async function handleMaterial(event){
 event.preventDefault();const form=event.currentTarget,data=new FormData(form),error=form.querySelector('#material-error'),button=form.querySelector('[type="submit"]'),status=form.querySelector('#upload-status');
 if(!form.reportValidity())return;error.textContent='';const file=data.get('file'),hasFile=file?.size>0,existing=state.items.find(i=>i.id===form.dataset.id);let item=existing,fileSaved=false;
 button.disabled=true;button.textContent='Жүктелуде...';
 try{if(form.dataset.id.startsWith('resource:')){await store.updateResourceMetadata(form.dataset.id.slice(9),{title:String(data.get('title')).trim(),description:String(data.get('description')).trim(),category:data.get('category'),subject:data.get('subject'),is_published:data.get('published')==='on'});await refreshCatalog();navigate('/admin/materials');showToast('Материал сәтті өңделді');return;}if(hasFile)validateFile(file);else if(!existing)throw new Error('Файл таңдалмады');button.disabled=true;button.textContent='Жүктелуде...';const parent=state.items.find(i=>i.id===data.get('parent_id'));if(!parent)throw new Error('Тақырыпты таңдаңыз');
 const patch={title:String(data.get('title')).trim(),description:String(data.get('description')).trim(),subject:data.get('subject'),category:data.get('category'),parent_id:parent.id,area:parent.area};
 if(!patch.title||!patch.description)throw new Error('Атауы мен сипаттамасын енгізіңіз');
 if(existing){item=await store.updateContent(existing.id,{...existing,...patch,is_published:existing.is_published});}
 else{item=await store.createContent({...patch,path:'/material/'+crypto.randomUUID(),item_type:'lesson',content_mode:'resources',body:'',video_url:'',quiz_data:{},sort_order:0,is_published:false});form.dataset.id=item.id;}
 if(hasFile)await store.uploadResource(item.id,file,p=>{status.innerHTML=`<label>Жүктелуде... ${p}%<progress max="100" value="${p}"></progress></label>`;});
 if(hasFile){fileSaved=true;form.querySelector('[name="file"]').value='';}
 const publish=data.get('published')==='on';await store.updateContent(item.id,store.mode==='local-server'?{...item,is_published:publish}:{is_published:publish});
 state.items=normalizeItems(await store.listContent(true));await refreshCatalog();navigate('/admin/materials');showToast('Материал сәтті қосылды');
 }catch(err){error.textContent=errorMessage(err)+(fileSaved?' Файл сақталды. Жариялау күйін тексеріп, қайта сақтаңыз.':item&&!existing?' Материал жоба ретінде сақталды. Файлды қайта жүктеңіз.':'');if(item){try{state.items=normalizeItems(await store.listContent(true));}catch{/* Keep the original upload error and the form for retry. */}}}
 finally{button.disabled=false;button.textContent='Сақтау';}
}
async function boot(){
 state.bootError=null;try{await store.init();state.user=await store.currentUser();state.items=normalizeItems(await store.listContent(state.user?.role==='admin'));await refreshCatalog();if(state.user?.role==='admin')state.users=await store.listUsers();else if(state.user)state.progress=await store.getProgress();try{const saved=await store.getSettings();state.settings={...DEFAULT_THEME,...saved};if(!saved.interface_version){for(const k of ["background","surface","text","muted","school","university","bridge","diagnostic"])state.settings[k]=DEFAULT_THEME[k];state.settings.visual_effects=false;}}catch(error){showToast(error.message,'error');}}
 catch(error){state.bootError=errorMessage(error);}finally{applyTheme();state.loading=false;render();hydrateRoute();}
}
window.addEventListener('storage',event=>{if(['chem_supabase_session_v1','chem_server_session_v1'].includes(event.key)){state.user=null;state.users=[];state.analytics=null;state.resources={};state.allResources=[];state.previewing=null;state.loading=true;render();boot();}});
render();boot();

window.addEventListener("unhandledrejection",event=>{event.preventDefault();showToast(errorMessage(event.reason),"error");});
